       ("ตอบกลับอธิบายว่าแต่ละจุดผิดเพราะอะไร เช่น ข้อมูลที่ได้รับมาไม่ครบ และมีเวลาทำน้อยกว่าที่ควร", 0.5, "ให้ข้อมูลบางส่วน แต่เน้นแก้ตัวมากกว่าแก้งาน"),
