                  "ถ้าอีกฝ่ายอยู่ในอันตรายหรือพูดถึงการทำร้ายตัวเอง ต้องแจ้งผู้ใหญ่หรือผู้เชี่ยวชาญทันที ไม่ใช่แค่รับฟัง\n\n"
                  "ถ้าเป็นห่วงเรื่องสุขภาพจิต โทร **1323** สายด่วนสุขภาพจิต กรมสุขภาพจิต ได้ตลอด 24 ชั่วโมง "
