       ("สั่งอาหารเผื่อ 150 ชุดในกล่องโฟม เพราะสะดวกที่สุดและกลัวอาหารไม่พอสำหรับแขกที่มาโดยไม่ได้ลงทะเบียน", 0.5, "ทำหน้าที่ดูแลอาหารได้ แต่เผื่อเกินข้อมูลและสร้างทั้งอาหารเหลือกับขยะโฟมจำนวนมาก"),
       ("ไม่จัดอาหารว่างเพื่อลดขยะ", 0.25, "ทิ้งหน้าที่ของฝ่ายสวัสดิการ"),
