# ============================================================ civic.local.participation
tid = C + "local.participation"
L = lesson(tid, "ชวนคนในพื้นที่มีส่วนร่วมตั้งแต่ต้น",
    "โครงการที่คนในพื้นที่ร่วมคิด ร่วมตัดสินใจ และร่วมทำ จะอยู่ได้นานกว่าโครงการที่คนนอกทำให้ ให้ชุมชนเป็นเจ้าของ ไม่ใช่ผู้รับ",
    objectives=["ชวนคนในพื้นที่ร่วมตั้งแต่ขั้นคิดและตัดสินใจ ไม่ใช่แค่ขั้นลงแรง",
                "ให้ชุมชนมีบทบาทเป็นเจ้าของโครงการ",
                "เปิดโอกาสให้ทุกกลุ่มในชุมชนมีเสียง"],
    prereq=[C + "local.understand_context"],
    blocks=[
        hook("\"เราทำให้เสร็จแล้ว ชุมชนแค่มารับไป\" ฟังดูใจดี แต่โครงการแบบนี้มักถูกทิ้งร้างหลังคนนอกกลับไป "
             "เพราะชุมชนไม่รู้สึกว่าเป็นของตัวเอง\n\n" + NOTE),
        concept("ระดับการมีส่วนร่วม",
                "1. **แจ้งให้ทราบ** — บอกว่าจะทำอะไร (มีส่วนร่วมน้อยที่สุด)\n"
                "2. **ขอความเห็น** — ถามแต่คนนอกเป็นคนตัดสินใจ\n"
                "3. **ร่วมตัดสินใจ** — ชุมชนร่วมเลือกว่าจะทำอะไร อย่างไร\n"
                "4. **ชุมชนเป็นเจ้าของ** — ชุมชนนำ คนนอกเป็นผู้สนับสนุน\n\n"
                "ตัวเลือกที่ให้ชุมชนอยู่ระดับ 3-4 มักได้คะแนนสูงกว่าระดับ 1-2"),
        technique("เปลี่ยนจาก 'ทำให้' เป็น 'ทำด้วย'",
                  "เมื่อวางแผนโครงการพัฒนาชุมชน",
                  "ในภาวะฉุกเฉิน การช่วยเหลือเร่งด่วนอาจต้องทำทันทีก่อน แล้วค่อยให้ชุมชนมีส่วนร่วมในช่วงฟื้นฟู",
                  "เชิญคนหลายกลุ่มในชุมชนมาคิดตั้งแต่ต้น รวมถึงกลุ่มที่เสียงเบา เช่น ผู้หญิง เยาวชน ผู้สูงอายุ "
                  "แบ่งบทบาทให้คนในชุมชนดูแลส่วนสำคัญ และวางแผนว่าหลังคนนอกกลับไป ใครในชุมชนจะดูแลต่อ",
                  tip="ร่วมคิด · ร่วมตัดสินใจ · ร่วมทำ · ร่วมดูแล"),
        example("ตัวอย่างที่ 1",
                "กลุ่มนักศึกษาจะสร้างลานเด็กเล่นในหมู่บ้าน",
                [("ร่วมคิด: จัดวงคุยกับผู้ปกครองและเด็กว่าอยากได้แบบไหน ตรงไหน", "ชุมชนเป็นคนกำหนดความต้องการ"),
                 ("ร่วมทำ: ชวนช่างในหมู่บ้านและผู้ปกครองช่วยสร้าง", "ชุมชนรู้วิธีซ่อมเมื่อชำรุด"),
                 ("ร่วมดูแล: ตั้งกลุ่มผู้ปกครองดูแลลาน", "ลานอยู่ได้หลังนักศึกษากลับไป")],
                "ให้ชุมชนร่วมตั้งแต่คิด สร้าง และดูแล"),
        pitfall("ชวนมาแค่ช่วยลงแรง",
                "เลือกตัวเลือกที่วางแผนเองทั้งหมด แล้วชวนชาวบ้านมาช่วยขนของในวันงาน",
                "ชาวบ้านมีส่วนร่วมแค่แรงงาน ไม่ได้ร่วมตัดสินใจ จึงไม่รู้สึกเป็นเจ้าของ",
                "ชวนร่วมตั้งแต่ขั้นคิดและตัดสินใจ",
                "token_participation"),
        summary("โครงการที่ชุมชนเป็นเจ้าของอยู่ได้นานกว่า",
                "ระดับการมีส่วนร่วม: แจ้ง · ขอความเห็น · ร่วมตัดสินใจ · เป็นเจ้าของ",
                "ชวนทุกกลุ่มรวมถึงกลุ่มที่เสียงเบา",
                "วางแผนว่าใครในชุมชนจะดูแลต่อ"),
        check("ข้อใดแสดงการมีส่วนร่วมของชุมชน **ระดับสูงที่สุด**",
              ["ติดประกาศแจ้งว่าจะมีโครงการ", "ส่งแบบสอบถามความเห็นแล้วทีมงานตัดสินเอง", "ชาวบ้านร่วมเลือกโครงการ วางแผน และตั้งกลุ่มดูแลเอง", "ชวนชาวบ้านมาถ่ายรูปในวันเปิดโครงการ"], 2,
              "ชาวบ้านร่วมตัดสินใจและเป็นเจ้าของโครงการ"),
    ])
